// three-tone round slice (carrot, sweet potato, banana, tomato base) in packshot pixels
function disc(cx, cy, rx, ry, rot, [base, dark, light], extra = '') {
  return `<g transform="rotate(${rot} ${cx} ${cy})"><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${dark}"/>`
    + `<ellipse cx="${r2(cx - rx * .06)}" cy="${r2(cy - ry * .06)}" rx="${r2(rx * .9)}" ry="${r2(ry * .9)}" fill="${base}"/>`
    + `<ellipse cx="${r2(cx - rx * .3)}" cy="${r2(cy - ry * .3)}" rx="${r2(rx * .42)}" ry="${r2(ry * .34)}" fill="${light}" opacity=".55"/>${extra}</g>`;
}
function tomato(cx, cy, rx, ry, rot) {
  let s = `<g transform="rotate(${rot} ${cx} ${cy})"><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="#a3170f"/>`
    + `<ellipse cx="${r2(cx - rx * .05)}" cy="${r2(cy - ry * .05)}" rx="${r2(rx * .93)}" ry="${r2(ry * .93)}" fill="#e2341f"/>`
    + `<ellipse cx="${cx}" cy="${cy}" rx="${r2(rx * .8)}" ry="${r2(ry * .8)}" fill="#f0553a"/>`;
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI / 2 + Math.PI / 4;
    const x = r2(cx + Math.cos(a) * rx * .42), y = r2(cy + Math.sin(a) * ry * .42);
    s += `<ellipse cx="${x}" cy="${y}" rx="${r2(rx * .26)}" ry="${r2(ry * .24)}" fill="#f88a5c" transform="rotate(${r2(a * 57.3)} ${x} ${y})"/>`
      + `<circle cx="${x}" cy="${y}" r="${r2(rx * .06)}" fill="#f7d38a"/><circle cx="${r2(x + rx * .08)}" cy="${r2(y + ry * .07)}" r="${r2(rx * .05)}" fill="#f7d38a"/>`;
  }
  return s + `<ellipse cx="${cx}" cy="${cy}" rx="${r2(rx * .16)}" ry="${r2(ry * .5)}" fill="#e6402a"/>`
    + `<ellipse cx="${r2(cx - rx * .35)}" cy="${r2(cy - ry * .45)}" rx="${r2(rx * .3)}" ry="${r2(ry * .14)}" fill="#fff" opacity=".22"/></g>`;
}
