// art layer and label for V8 Strawberry Banana, in packshot pixels of the Kroger render (982 px tall)
function strawberryHalf(cx, cy, w, h) {
  const p = (a, b, c, d) => `M${cx} ${r2(cy + h * .5)}C${r2(cx - w * a)} ${r2(cy + h * .2)} ${r2(cx - w * b)} ${r2(cy - h * .45)} ${cx} ${r2(cy - h * c)}C${r2(cx + w * b)} ${r2(cy - h * .45)} ${r2(cx + w * a)} ${r2(cy + h * .2)} ${cx} ${r2(cy + h * .5)}Z`;
  return `<path d="${p(.55, .62, .4)}" fill="#a3101c"/><path d="${p(.48, .55, .37)}" fill="#e02634"/><path d="${p(.36, .42, .3)}" fill="#f6a3a3" transform="translate(0 2)"/>`
    + `<path d="M${cx} ${r2(cy - h * .26)}C${r2(cx - w * .14)} ${r2(cy - h * .05)} ${r2(cx - w * .08)} ${r2(cy + h * .25)} ${cx} ${r2(cy + h * .38)}C${r2(cx + w * .08)} ${r2(cy + h * .25)} ${r2(cx + w * .14)} ${r2(cy - h * .05)} ${cx} ${r2(cy - h * .26)}Z" fill="#fde3df"/>`;
}
function strawberry(cx, cy, w, h, rot) {
  let s = `<g transform="rotate(${rot} ${cx} ${cy})"><path d="M${cx} ${r2(cy + h * .5)}C${r2(cx - w * .6)} ${r2(cy + h * .25)} ${r2(cx - w * .62)} ${r2(cy - h * .5)} ${cx} ${r2(cy - h * .45)}C${r2(cx + w * .62)} ${r2(cy - h * .5)} ${r2(cx + w * .6)} ${r2(cy + h * .25)} ${cx} ${r2(cy + h * .5)}Z" fill="#b5121e"/>`
    + `<path d="M${r2(cx - 3)} ${r2(cy + h * .44)}C${r2(cx - w * .52)} ${r2(cy + h * .2)} ${r2(cx - w * .52)} ${r2(cy - h * .44)} ${r2(cx - 3)} ${r2(cy - h * .4)}C${r2(cx + w * .4)} ${r2(cy - h * .44)} ${r2(cx + w * .4)} ${r2(cy + h * .2)} ${r2(cx - 3)} ${r2(cy + h * .44)}Z" fill="#e8303a"/>`
    + `<ellipse cx="${r2(cx - w * .2)}" cy="${r2(cy - h * .18)}" rx="${r2(w * .13)}" ry="${r2(h * .16)}" fill="#ff8a86" opacity=".6"/>`;
  for (const [dx, dy] of [[-.25, -.2], [0, -.25], [.22, -.18], [-.3, .02], [-.08, 0], [.15, .02], [.3, .05], [-.2, .2], [.05, .22], [-.05, .38]]) s += `<ellipse cx="${r2(cx + w * dx)}" cy="${r2(cy + h * dy)}" rx="2.2" ry="3" fill="#f7d36a"/>`;
  return s + `</g>`;
}
